"""Build a standalone HTML report from the actual example outputs (Matplotlib optional to app)."""
import json, csv, pathlib, html
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=pathlib.Path(__file__).resolve().parents[1]
data=json.loads((root/'docs/results/summary.json').read_text())
plt.rcParams.update({'font.family':'sans-serif','font.sans-serif':['Arial','Liberation Sans','DejaVu Sans'],'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.edgecolor':'#c9d2c2','axes.labelcolor':'#425637','xtick.color':'#718264','ytick.color':'#718264','figure.facecolor':'white','axes.facecolor':'white'})
# Scientific geometry view generated directly from the app's spatial graph.
from mpl_toolkits.mplot3d.art3d import Line3DCollection
geom=json.loads((root/'docs/results/unit-cell-geometry.json').read_text())
fig=plt.figure(figsize=(10,4.8),layout='constrained')
for i,cut in enumerate([False,True]):
    ax=fig.add_subplot(1,2,i+1,projection='3d')
    ax.set_proj_type('persp')
    for level,color,lw in [(0,'#6f8b43',2.4),(1,'#acb979',1.15),(2,'#b7c89b',.8)]:
        segs=[]
        for e in geom['edges']:
            if e['level']!=level: continue
            a,b=[geom['nodes'][e[k]] for k in ('a','b')]
            if cut and (a['z']+b['z'])/2>geom['depth']*.52: continue
            segs.append([(n['x'],n['z'],n['y']) for n in (a,b)])
        if segs: ax.add_collection3d(Line3DCollection(segs,colors=color,linewidths=lw,alpha=.9))
    ax.set(xlim=(0,geom['width']),ylim=(0,geom['depth']),zlim=(0,geom['height']),xlabel='X (mm)',ylabel='Z (mm)',zlabel='Y (mm)')
    ax.set_box_aspect((geom['width'],geom['depth'],geom['height']));ax.view_init(elev=23,azim=-55)
    ax.set_title('Interior view · front portion only' if cut else 'Canopy · complete spatial unit cell',fontsize=12,pad=12)
    for axis in [ax.xaxis,ax.yaxis,ax.zaxis]:
        axis.pane.fill=False;axis._axinfo['grid']['color']=(.75,.8,.7,.25)
fig.savefig(root/'docs/results/unit-cell-3d.png',dpi=180)
fig.savefig(root/'docs/results/unit-cell-3d.svg')
plt.close(fig)

fig,axs=plt.subplots(2,3,figsize=(12,6.5),constrained_layout=True)
titles={'canopy_tension':'Hierarchical canopy · tension','crystal_tension':'Ordered Kelvin cell · X tension','notched_fracture':'Notched canopy · member fracture','neo_compression':'Re-entrant · Z compression','plastic_cycle':'Octet cell · axial plastic cycle','canopy_shear':'Hierarchical canopy · Z shear'}
for ax,item in zip(axs.flat,data['experiments']):
    rows=list(csv.DictReader((root/f"docs/results/{item['name']}.csv").open()))
    x=[100*float(r['strain']) for r in rows]; y=[float(r['force']) for r in rows]
    ax.plot(x,y,color='#759250',lw=1.8,marker='.',ms=3)
    ax.set_title(titles[item['name']],loc='left',fontsize=10,pad=11)
    ax.set_xlabel('Applied strain (%)');ax.set_ylabel('Reaction (N)');ax.grid(axis='y',alpha=.22)
    if item['failure']:
        ax.text(.96,.95,f"Stopped at {100*item['failure']['strain']:.1f}%\nUnconverged step excluded",transform=ax.transAxes,va='top',ha='right',fontsize=8,color='#a26839',bbox={'facecolor':'white','edgecolor':'none','alpha':.85})
fig.savefig(root/'docs/results/response-curves.png',dpi=170);fig.savefig(root/'docs/results/response-curves.svg');plt.close(fig)
rows=[]
for item in data['experiments']:
    fail=item['failure'];status='Completed' if not fail else f"Stopped at {100*fail['strain']:.1f}% (relative residual {fail['residual']:.3g})"
    rows.append(f"<tr><td>{html.escape(titles[item['name']])}</td><td>{item['nodes']} / {item['struts']}</td><td>{item['points']}</td><td>{item['maximumReaction']:.3f} N</td><td>{item['failedStruts']}</td><td>{item['seconds']:.2f} s</td><td>{status}</td></tr>")
prints=[]
for p in data['prints']:
    prints.append(f"<tr><td>{p['profile']}</td><td>{p['triangles']:,}</td><td>{p['components']}</td><td>{p['nonManifoldEdges']} / {p['orientationErrors']}</td><td>{p['volume']/1000:.3f} cm³</td><td>{' × '.join(f'{x:.2f}' for x in p['dimensions'])} mm</td></tr>")
document='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Canopy — Verification and example results</title><style>body{font-family:Arial,Helvetica,sans-serif;color:#294234;max-width:1180px;margin:45px auto;padding:0 28px;line-height:1.7}h1{font-size:36px;font-weight:400;letter-spacing:-1px;margin-bottom:0}h2{font-size:22px;font-weight:400;margin-top:35px}p{color:#67795c}small{color:#809471}table{border-collapse:collapse;width:100%;font-size:13px;margin:18px 0}th{text-align:left;background:#eef3e7;font-weight:500}td,th{padding:11px;border-bottom:1px solid #dce4d1}img{max-width:100%;height:auto}a{color:#50722f}.note{padding:16px 20px;border-left:3px solid #8ea771;background:#f4f7ef}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}code{background:#f0f4e9;padding:2px 5px}@media(max-width:700px){.grid{grid-template-columns:1fr}table{display:block;overflow:auto}}@media print{body{margin:15px;max-width:none}h2{break-after:avoid}tr,img{break-inside:avoid}}</style><body><small>CANOPY / METAMATERIAL STUDIO</small><h1>Verification and example results</h1><p>Actual outputs from the included JavaScript solver and fused STL exporter. Generated '''+html.escape(data['generatedAt'])+'''.</p><div class="note">The studio computes quasi-static spatial beam mechanics with three translations and three rotations per node, including bending in both planes and torsion. These numerical examples establish implementation behavior and known limits; they do not replace calibration against physical printed specimens.</div><h2>The volumetric unit cell</h2><p>The actual default graph has 96 nodes and 192 struts distributed through a 36 × 36 × 36 mm volume. Thick primary members surround finer inset cages; shared face nodes allow XYZ assembly. The figure below plots the generated graph directly.</p><img src="results/unit-cell-3d.png" alt="Perspective and partially cut-away views of the actual 3D hierarchical cell."><h2>Mechanical experiments</h2><p>All curves below contain converged load steps only. All six included paths complete. The notched case loses its spanning load path after 20 struts fail; its subsequent reaction is effectively zero. Plastic unloading returns to zero prescribed displacement, leaving a compressive reaction from permanent axial strain. Reaction values are determined by the chosen topology, radius, boundary conditions, and material constants; the cases are demonstrations, not a controlled ranking at equal mass.</p><img src="results/response-curves.png" alt="Six measured numerical force–strain responses, including a notched fracture case and plastic unloading loop."><table><thead><tr><th>Case</th><th>Nodes / struts</th><th>Points</th><th>Peak reaction</th><th>Failed struts*</th><th>Compute time</th><th>Outcome</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><p><small>*Includes failed members committed in converged fracture-cascade states at the final imposed displacement, even if the subsequent post-deletion equilibrium cannot be recovered. Timing is measured on the build machine using Node.js, not a guaranteed browser frame rate. Large networks and low-power devices will differ.</small></p><h2>Printing checks</h2><p>These reference STL files use unsimplified surfaces. Version 2.1 adds a separate fine adaptive STL and <a href="MESHING.md">adaptive meshing report</a>, including measured triangle reduction and volume change.</p><p>The three supplied example STL files use the same volumetric hierarchical unit cell, a 32 mm nominal centerline width, 0.8 mm minimum diameter, and a 0.28 mm voxel grid. Their outside dimensions include thickness. All three are fused closed meshes with consistent winding and one connected component.</p><table><thead><tr><th>Profile</th><th>Triangles</th><th>Solids</th><th>Open edges / orientation errors</th><th>Volume</th><th>Outside dimensions</th></tr></thead><tbody>'''+''.join(prints)+'''</tbody></table><h2>Verification coverage</h2><div class="grid"><div><p><strong>Mechanics</strong></p><ul><li>Linear and Neo-Hookean constitutive response and energy derivatives.</li><li>Plastic return mapping, permanent strain, and elastic unloading.</li><li>Spatial force equals the energy gradient for all three material classes; the quasi-Newton tangent matches the exact stiffness at rest.</li><li>Zero energy under translation and large rigid rotation.</li><li>Axial bar: reaction EAε and stored energy EA Lε²/2.</li><li>Cantilever deflection in both transverse planes: FL³/(3EI).</li><li>Torsional rotation: TL/(GJ), and stored torsional energy.</li><li>Notch removal, whole-member fracture, and equilibrium force balance.</li></ul></div><div><p><strong>Geometry and STL</strong></p><ul><li>Deterministic connected geometry for every preset.</li><li>Coincident nodes merged across repeated tile seams.</li><li>All three thickening profiles form closed oriented meshes.</li><li>XYZ repeats share face nodes; spatial export preserves depth.</li><li>Legacy planar layer connectors still join a stack into one solid.</li><li>Binary STL triangle counts and byte lengths match.</li><li>Under-resolved and excessively large exports fail explicitly.</li></ul></div></div><p>Run <code>node --test tests/*.test.mjs</code> to run the current automated checks. Static source validation separately checks module syntax, referenced assets, worker paths, and control identities. No automated browser interaction or physical experiment was performed.</p><h2>Files and interpretation</h2><p><a href="METHODS.md">Full methods</a> · <a href="results/summary.json">Parameters and numerical summary</a> · <a href="results/response-curves.svg">Vector plots</a> · <a href="../README.md">Local app instructions</a>. Raw CSV files are in <code>docs/results</code>; example STL files and importable designs are in <code>examples</code>.</p><p>Spatial fracture uses tensile principal stress including axial, bending, and torsional contributions, with irreversible whole-strut deletion. It has no calibrated fracture-energy regularization. Nonlinear material classes affect axial behavior; bending and torsion retain reference-section elasticity. The 3D beam model permits out-of-plane deformation but does not certify global stability or a buckling load. Self-contact, solid junction stresses, plastic bending/torsion, and printing defects are omitted. Spatial XYZ repeats participate in mechanics; legacy planar print layers remain geometry only. See the methods before treating any result as a quantitative material prediction.</p></body></html>'''
(root/'docs/REPORT.html').write_text(document)
print('Wrote docs/REPORT.html and response plots.')
